__NUXT_JSONP__("/fr/firstday-at-mli", (function(a){return {data:[{details:{slug:"fr",pageTitle:"Le premier jour à MLI | Mentor Language Institute",pageDescription:a,title:"Le premier jour à MLI",image:"\u002Fimages\u002Fwhat-is-mli\u002Ffirst-day-at-mli\u002Fmli-signup.jpg",categories:[{title:"Bienvenue à Mentor Language Institute!",description:[a,"L'orientation vous fournira des informations importantes et nécessaires à propos de nos programmes, des règlements d'immigration, des règles de l'école mais aussi pour vous aider à atteindre tous vos objectifs scolaires."],dates:["＜Les dates de début de chaque terme＞","- May 22nd, 2023 \u003Cbr\u002F\u003E - June 20th, 2023 \u003Cbr\u002F\u003E - July 17th, 2023 \u003Cbr\u002F\u003E - August 14th, 2023 \u003Cbr\u002F\u003E - September 11th, 2023 \u003Cbr\u002F\u003E - October 10th, 2023 \u003Cbr\u002F\u003E - November 6th, 2023 \u003Cbr\u002F\u003E - December 4th, 2023 \u003Cbr\u002F\u003E - January 8th, 2024 \u003Cbr\u002F\u003E - February 5th, 2024 \u003Cbr\u002F\u003E - March 4th, 2024","l'orientation commencent à 1:00 pm."],groups:[{title:"Orientation et test de niveau",listType:"table",lists:[{key:"1:00pm – 1:30pm",value:"Documents d'inscription"},{key:"1:30pm – 2:00pm",value:"Orientation académique"},{key:"2:00pm – 3:00pm",value:"Test de niveau"},{key:"3:15pm – 3:35pm",value:"Règlements de l'école et d'immigration"},{key:"3:35pm – 3:50pm",value:"Service de transfert au collège"},{key:"3:50pm – 4:00pm",value:"Activités et logement"},{key:"4:00pm – 4:10pm",value:"Test d'élocution et placement en classe"},{key:"4:10pm – 4:20pm",value:"Achat des livres"}]},{title:"Qu'est ce que vous avez besoin d'apporter avec vous le premier jour?",lists:["Passeport (Si vous êtes titulaire d'un visa étudiant)","I-20 (Si vous êtes titulaire d'un visa étudiant)","Stylo et papier","Moyen de paiement pour l'achat des livres et de s'acquitter des frais de scolarité"]}]},{title:"Détails",groups:[{title:"Horaire d'orientation",description:["Vous commencerez par remplir les documents nécessaires pour l'inscription.\u003Cbr \u002F\u003EEnsuite, le directeur académique ou le coordinateur de programme fera une présentation sur nos différents programmes, règlement de classe, et comment réussir ses études pour passer d'un niveau à un autre et d'un programme à un autre."]},{title:"Test de niveau et interview",description:["Après l'orientation, vous passerez le «test de niveau en anglais» qui comprend environ 80 questions, avec une partie de comréhension à l'audition et une partie qui couvre la grammaire, le vocabulaire et la compréhension à la lecture. C'est un test de 60 minutes qui aide à déterminer votre niveau d'anglais.\u003Cbr \u002F\u003EAprès le test, vous aurez un test d'expression orale rapide (plus comme une interview) avec l'un de nos instructeurs (soit le Program Coordinator, l'Academic Directeur ou un enseignant de MLI). Ce test est destiné à déterminer le niveau d'anglais adequat et\u002Fou le programme le plus approprié en fonction de vos compétences et de vos objectifs."]},{title:"Achat de manuels scolaires",description:["Après le test de niveau et l'interview, les élèves achètent leurs livres auprès du personnel de la réception qui est disponible pour répondre aux questions ou préoccupations supplémentaires des étudiants."]}]}],dir:"\u002Ffirstday-at-mli",path:"\u002Ffirstday-at-mli\u002Ffr",extension:".json",createdAt:"2026-10-22T16:31:29.260Z",updatedAt:"2025-05-26T12:06:27.755Z"}}],fetch:{},mutations:void 0}}("A MLI, nous organisons une séance d'orientation pour les nouveaux étudiants au début de chaque module (toutes les 4 semaines).")));